target.css:
:root {
  --ink: #18354a;
  --muted: #6c8391;
  --paper: #ffffff;
  --line: #d6e6e7;
  --aqua: #dff5ef;
  --teal: #167b79;
  --coral: #f07f69;
  --sun: #f7c85c;
  --soft-coral: #fff0ec;
}

* {
  box-sizing: border-box;
}

.tank-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  background: var(--aqua);
  border-bottom: 1px solid var(--line);
}

.tank-title {
  display: flex;
  align-items: center;
  gap: 10px;
}

.reef-mark {
  display: grid;
  width: 33px;
  height: 33px;
  place-items: center;
  font-size: 20px;
  background: var(--paper);
  border-radius: 10px;
}

.eyebrow,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  line-height: 1.2;
}

h1 {
  margin: 3px 0 0;
  font-size: 19px;
  line-height: 1;
}

.status {
  padding: 5px 8px;
  color: var(--teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .8px;
  background: var(--paper);
  border: 1px solid var(--teal);
  border-radius: 999px;
}

.tank-main {
  display: grid;
  grid-template-columns: 1.12fr .88fr;
  min-height: 157px;
}

.readings,
.protocol {
  padding: 14px 16px;
}

.readings {
  border-right: 1px solid var(--line);
}

.metric-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-top: 9px;
}

.metric {
  display: flex;
  flex-direction: column;
  min-height: 51px;
  padding: 7px 9px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 9px;
}

.metric span,
.metric small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1;
}

.metric strong {
  margin: 3px 0 2px;
  font-size: 16px;
  line-height: 1;
}

.metric.warm {
  border-color: var(--sun);
}

.metric.alert {
  background: var(--soft-coral);
  border-color: var(--coral);
}

.protocol {
  background: var(--paper);
}

.protocol-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.protocol-head span {
  color: var(--coral);
  font-size: 12px;
  font-weight: 800;
}

.checklist {
  display: grid;
  gap: 8px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.checklist li {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  line-height: 1.1;
}

.check {
  display: grid;
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  place-items: center;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  border: 1px solid var(--line);
  border-radius: 50%;
}

.check.done {
  color: var(--paper);
  background: var(--teal);
  border-color: var(--teal);
}

time {
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
}

.tank-footer {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  color: var(--muted);
  font-size: 11px;
  background: var(--aqua);
  border-top: 1px solid var(--line);
}

.tank-footer strong {
  color: var(--ink);
}

button {
  margin-left: auto;
  padding: 7px 10px;
  color: var(--paper);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  background: var(--ink);
  border: 0;
  border-radius: 8px;
}

button span {
  margin-left: 5px;
  color: var(--sun);
  font-size: 14px;
}

